87	    /**
88	     * Helper method to convert the latest result of a submission to a PyrisResultDTO
89	     *
90	     * @param submission the submission
91	     * @return the PyrisResultDTO or null if the submission has no result
92	     */
93	    private PyrisResultDTO getLatestResult(ProgrammingSubmission submission) {
94	        var latestResult = submission.getLatestResult();
95	        if (latestResult == null) {
96	            return null;
97	        }
98	        var feedbacks = latestResult.getFeedbacks().stream().map(feedback -> {
99	            var text = feedback.getDetailText();
100	            if (feedback.getHasLongFeedbackText()) {
101	                text = feedback.getLongFeedback().orElseThrow().getText();
102	            }
103	            var testCaseName = feedback.getTestCase() == null ? feedback.getText() : feedback.getTestCase().getTestName();
104	            return new PyrisFeedbackDTO(text, testCaseName, Objects.requireNonNullElse(feedback.getCredits(), 0D));
105	        }).toList();
106	
107	        return new PyrisResultDTO(toInstant(latestResult.getCompletionDate()), latestResult.isSuccessful(), feedbacks);
108	    }
