110	    private Map<String, String> getFilteredRepositoryContents(ProgrammingExerciseParticipation participation) {
111	        var language = participation.getProgrammingExercise().getProgrammingLanguage();
112	
113	        var repositoryContents = getRepositoryContents(participation.getVcsRepositoryUri());
114	        return repositoryContents.entrySet().stream().filter(entry -> language == null || language.matchesFileExtension(entry.getKey()))
115	                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
116	    }
