120	     * This is an exception safe way to fetch the repository, as it will return an empty map if the repository could not be fetched.
121	     * This is useful, as the Pyris call should not fail if the repository is not available.
122	     *
123	     * @param repositoryUri the repositoryUri of the repository
124	     * @return the repository or empty if it could not be fetched
125	     */
126	    private Map<String, String> getRepositoryContents(LocalVCRepositoryUri repositoryUri) {
127	        try {
128	            return repositoryService.getFilesContentFromBareRepositoryForLastCommit(repositoryUri);
129	        }
130	        catch (IOException e) {
131	            log.error("Could not get repository content", e);
132	            return Map.of();
133	        }
134	    }

