98	     * Executes a pipeline on Pyris, identified by the given name and variant.
99	     * The pipeline execution is tracked by a unique job token, which must be provided by the caller.
100	     * The caller must additionally provide a mapper function to create the concrete DTO type for this pipeline from the base DTO.
101	     * The status of the pipeline execution is updated via a consumer that accepts a list of stages. This method will
102	     * call the consumer with the initial stages of the pipeline execution. Later stages will be sent back from Pyris,
103	     * and need to be handled in the endpoint that receives the status updates.
104	     * <p>
105	     *
106	     * @param name          the name of the pipeline to be executed
107	     * @param variant       the variant of the pipeline
108	     * @param event         an optional event variant that can be used to trigger specific event of the given pipeline
109	     * @param jobToken      a unique job token for tracking the pipeline execution
110	     * @param dtoMapper     a function to create the concrete DTO type for this pipeline from the base DTO
111	     * @param statusUpdater a consumer to update the status of the pipeline execution
112	     */
113	    public void executePipeline(String name, String variant, Optional<String> event, String jobToken, Function<PyrisPipelineExecutionDTO, Object> dtoMapper,
114	            Consumer<List<PyrisStageDTO>> statusUpdater) {
115	        // Define the preparation stages of pipeline execution with their initial states
116	        // There will be more stages added in Pyris later
117	        var preparing = new PyrisStageDTO("Preparing", 10, null, null);
118	        var executing = new PyrisStageDTO("Executing pipeline", 30, null, null);
119	
120	        // Send initial status update indicating that the preparation stage is in progress
121	        statusUpdater.accept(List.of(preparing.inProgress(), executing.notStarted()));
122	
123	        var baseDto = new PyrisPipelineExecutionDTO(new PyrisPipelineExecutionSettingsDTO(jobToken, artemisBaseUrl, variant), List.of(preparing.done()));
124	        var pipelineDto = dtoMapper.apply(baseDto);
125	
126	        try {
127	            // Send a status update that preparation is done and pipeline execution is starting
128	            statusUpdater.accept(List.of(preparing.done(), executing.inProgress()));
129	
130	            try {
131	                // Execute the pipeline using the connector service
132	                pyrisConnectorService.executePipeline(name, pipelineDto, event);
133	            }
134	            catch (PyrisConnectorException | IrisException e) {
135	                log.error("Failed to execute {} pipeline", name, e);
136	                statusUpdater.accept(List.of(preparing.done(), executing.error("An internal error occurred")));
137	            }
138	        }
139	        catch (Exception e) {
140	            log.error("Failed to prepare {} pipeline execution", name, e);
141	            statusUpdater.accept(List.of(preparing.error("An internal error occurred"), executing.notStarted()));
142	        }
143	    }
