    private Optional<Exercise> getExerciseForPost(Post post) {
        if (post.getConversation() instanceof Channel channel && channel.getExercise() != null) {
            return exerciseRepository.findById(channel.getExercise().getId());
        }
        return Optional.empty();
    }

